#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 998244353;
int n;
static inline bool check(int i,int x,bool isL,int lp,int rp){
    int lam = lp + (isL ? 1 : 0);
    int r = rp + (isL ? 0 : 1);
    if(isL && lam == (i +1) / 2 && r <= n - i) return true;
    if(x == n - i /2 && rp >= n - i) return true;
    if(!isL && r == (n - i + 2) / 2 && lam <= i - 1) return true;
    if(x == (n + i) / 2 && lp >= i - 1) return true;
    return false;
}




int main() {
	// your code goes here
    int t;
    scanf("%d",&t);
    while(t--){
        scanf("%d",&n);
        vector<int> a(n + 1), start(n + 2,0), ord(n);
        for(int i = 1;i <= n; i++){
            scanf("%d", &a[i]);
            start[a[i] + 1]++;
        }
        for(int v= 1;v <= n+1;v++)start[v] += start[v-1];
        {
            vector<int> fill_pos(start.begin(),start.end());
            for(int i = 1; i <= n;i++) ord[fill_pos[a[i]]++] = i;
        }
        vector<int> dp(n+3,0),nd(n+3,0);
        dp[0] = 1;
        for(int v = 1;v <= n;v++){
            fill(nd.begin(),nd.begin() + v + 2,0);
            int gs = start[v], ge = start[v + 1];
            for(int lp = 0;lp < v;lp++){
                if(!dp[lp]) continue;
                int rp = v - 1 - lp;
                bool okL = true;
                for(int k = gs;k < ge;k++)
                if(!check(ord[k],v,true,lp,rp)) { okL = false;break;}
                if(okL){
                    nd[lp+1] += dp[lp];
                    if(nd[lp + 1] >= MOD) nd[lp + 1] -= MOD;
                }
                if(v < n){
                    bool okR = true;
                    for(int k = gs;k < ge;k++)
                    if(!check(ord[k] , v, false,lp,rp)){
                        okR = false;break;}
                    if(okR){
                        nd[lp] += dp[lp];
                        if(nd[lp] >= MOD) nd[lp] -= MOD;
                    }
                }
            }
            swap(dp,nd);
        }
        ll ans = 0;
        for(int l = 0;l <= n ; l++) ans += dp[l];
        
        printf("%lld\n",ans % MOD);
    }
    return 0;
}
